fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Ensure both vectors have the same length
    assert_eq!(a.len(), b.len());

    // Consume both vectors, pair up elements, compute remainder, and collect into a new Vec
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x % y)
     .collect()
}

